  ('ramayana-manas-angada-immovable-foot-v1', 'war', 1, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_WAR_MESSENGERS_DB_V1","expectationId":"manas-angada-immovable-foot","storyId":"ramayana-manas-angada-immovable-foot-v1","sourceId":"ramcharitmanas-belvedere-fixed-scan","scanSha256":"6d570d531ebada1912f6e930212393fec2200765a0b731b73b8e7135ea0f70f2","kanda":"Lankakanda","scanPagesInclusive":[943,965],"dohaRangeInclusive":[17,34],"secondaryLocator":"IITK Lankakanda, Angada''s embassy through the planted-foot episode, approximately doha 17-34"}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["rama","angada","jambavan","ravana","hanuman","sugriva","mandodari","indrajit"],"places":["Rama''s camp outside Lanka","the gates of Lanka","Ravana''s royal court"],"relationships":[{"target_kind":"story_cycle","target_id":"lanka-surrounded","relationship":"adds_final_embassy_inside","inverse_relationship":"contains_expression_specific_embassy","bidirectional":true},{"target_kind":"entity","target_id":"angada","relationship":"centres_on","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"ravana","relationship":"confronts","inverse_relationship":"is_confronted_in","bidirectional":true},{"target_kind":"story","target_id":"ramayana-manas-kalnemi-deception-v1","relationship":"precedes_later_war_mission","inverse_relationship":"follows_earlier_embassy","bidirectional":true}],"expressionScope":"ramcharitmanas"}'::jsonb),
