  ('ramayana-manas-bharata-shoots-hanuman-v1', 'war', 3, 3, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_WAR_MESSENGERS_DB_V1","expectationId":"manas-bharata-shoots-hanuman","storyId":"ramayana-manas-bharata-shoots-hanuman-v1","sourceId":"ramcharitmanas-belvedere-fixed-scan","scanSha256":"6d570d531ebada1912f6e930212393fec2200765a0b731b73b8e7135ea0f70f2","kanda":"Lankakanda","scanPagesInclusive":[988,991],"dohaRangeInclusive":[58,60],"secondaryLocator":"IITK Lankakanda, Hanuman over Ayodhya and Bharata meeting, approximately doha 58-60"}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["hanuman","bharata","rama","lakshmana","sita","sushena"],"places":["the night sky over Ayodhya","Nandigrama","the route from Ayodhya to Lanka","Rama''s battlefield camp"],"relationships":[{"target_kind":"story_cycle","target_id":"indrajits-last-war","relationship":"adds_ayodhya_encounter_inside_medicine_mission","inverse_relationship":"contains_expression_specific_ayodhya_encounter","bidirectional":true},{"target_kind":"entity","target_id":"bharata","relationship":"centres_on","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"hanuman","relationship":"centres_on","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"story","target_id":"ramayana-manas-kalnemi-deception-v1","relationship":"follows_on_same_medicine_journey","inverse_relationship":"precedes_on_same_medicine_journey","bidirectional":true}],"expressionScope":"ramcharitmanas"}'::jsonb)
