) as source(moment_slug, beat_slug, beat_ordinal, source_range)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-war-messengers-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
on conflict (moment_id, slug) do update set beat_ordinal=excluded.beat_ordinal, source_range=excluded.source_range,
  visual_direction=excluded.visual_direction, rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_beat_texts (beat_id, language_code, title, narration, text_status, rights_lane, publication_state)
select beat.id, source.language_code, source.title, source.narration, 'source_aligned', 'derivative_allowed', 'draft'
from (values
  ('ramayana-manas-angada-immovable-foot-v1', 'rama-asks-for-counsel-before-war', 'en', 'Rama asks whether one more message should be sent', 'At dawn outside Lanka, Rama gathers the leaders and asks what should be done before the battle advances. Jambavan recommends one last diplomatic attempt and names Angada, Bali''s son, as the envoy whose courage, judgment and royal standing can carry both warning and opportunity into Ravana''s court.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'rama-asks-for-counsel-before-war', 'hi', 'राम युद्ध से पहले एक और संदेश पर विचार करते हैं', 'लंका के बाहर प्रातः राम प्रमुख साथियों को बुलाकर पूछते हैं कि युद्ध आगे बढ़ाने से पहले क्या करना उचित होगा। जाम्बवान एक अंतिम दूत-प्रयास की सलाह देते हैं और बालीपुत्र अंगद को चुनते हैं, जिनका साहस, विवेक और राजवंशी स्थान रावण की सभा तक चेतावनी और अंतिम अवसर दोनों पहुँचा सकता है।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-receives-the-mission', 'en', 'Angada carries Rama''s purpose into Lanka', 'Rama entrusts Angada with speaking for the good of both sides: Ravana should return Sita and abandon a conflict that will destroy his people. Angada bows, holds Rama''s authority in mind and enters Lanka without uncertainty. His task is not a private contest of pride but a final effort to avert ruin.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-receives-the-mission', 'hi', 'अंगद राम का उद्देश्य लेकर लंका जाते हैं', 'राम अंगद को दोनों पक्षों के हित की बात कहने भेजते हैं: रावण सीता को लौटा दे और उस युद्ध को छोड़ दे जो उसके लोगों का विनाश करेगा। अंगद प्रणाम करके राम का प्रताप मन में रखते हैं और निर्भय होकर लंका में प्रवेश करते हैं। उनका काम निजी अहंकार की लड़ाई नहीं, विनाश रोकने का अंतिम प्रयास है।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-enters-ravanas-court', 'en', 'The envoy takes his place among Ravana''s commanders', 'After a violent encounter at the entrance, Angada reaches the royal assembly and enters with the confidence of a lion among elephants. He observes courtly form without surrendering his mission. Ravana asks who he is, and Angada identifies himself as Bali''s son before turning the exchange toward Rama''s demand.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-enters-ravanas-court', 'hi', 'दूत रावण के सेनापतियों के बीच सभा में बैठता है', 'प्रवेश के समय हुए हिंसक टकराव के बाद अंगद राजसभा तक पहुँचते हैं और मतवाले हाथियों के बीच सिंह जैसी निर्भीकता से बैठते हैं। वे दूत की मर्यादा रखते हैं, पर उद्देश्य नहीं छोड़ते। रावण परिचय पूछता है तो अंगद स्वयं को बाली का पुत्र बताते हुए बातचीत को राम की माँग की ओर ले जाते हैं।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-offers-the-last-way-back', 'en', 'Angada tells Ravana that surrender can still prevent destruction', 'Angada reminds Ravana of his lineage and capability, making the warning sharper rather than merely insulting him. Rama''s offer is direct: set pride aside, acknowledge the wrong done to Sita, return her and seek refuge before the war consumes Lanka. The envoy frames repentance as a remaining choice, not humiliation for its own sake.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-offers-the-last-way-back', 'hi', 'अंगद बताते हैं कि लौटने का मार्ग अभी भी खुला है', 'अंगद रावण को उसके वंश और सामर्थ्य की याद दिलाते हैं, ताकि चेतावनी केवल अपमान न रह जाए बल्कि अधिक गंभीर बने। राम का प्रस्ताव स्पष्ट है: अहंकार छोड़ो, सीता के साथ हुए अन्याय को स्वीकारो, उन्हें लौटाओ और युद्ध से पहले शरण लो। दूत पश्चात्ताप को केवल नीचा दिखाने के लिए नहीं, अब भी बची हुई वास्तविक राह के रूप में रखते हैं।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'ravana-and-angada-trade-boasts', 'en', 'The warning turns into a contest over power and memory', 'Ravana dismisses Rama as a mere human and attacks Angada''s loyalty, while Angada answers with reminders of Ravana''s former defeats, Hanuman''s burning of Lanka and Rama''s victories. Their long exchange exposes the central deadlock: every fact meant to break Ravana''s confidence is absorbed into a new boast rather than reconsidered.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'ravana-and-angada-trade-boasts', 'hi', 'चेतावनी शक्ति और पुरानी पराजयों की बहस बन जाती है', 'रावण राम को साधारण मनुष्य बताकर अंगद की निष्ठा पर आघात करता है। अंगद उत्तर में रावण की पुरानी पराजयों, हनुमान द्वारा लंका-दहन और राम की विजय का स्मरण कराते हैं। लंबी बहस मूल गतिरोध खोल देती है: रावण का विश्वास तोड़ने वाला हर तथ्य पुनर्विचार का कारण बनने के बजाय नए घमंड में बदल जाता है।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-refuses-personal-defection', 'en', 'Ravana cannot turn Bali''s son against Rama', 'Ravana tries ridicule, appeals to Bali''s memory and claims of superior strength, hoping the envoy''s family history can be used against Rama. Angada refuses the separation. He treats service to Rama as a deliberate allegiance and makes clear that neither a promised advantage nor an old grievance will convert the embassy into betrayal.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-refuses-personal-defection', 'hi', 'रावण बाली के पुत्र को राम से नहीं तोड़ पाता', 'रावण उपहास, बाली की स्मृति और अपनी शक्ति के दावों से अंगद को प्रभावित करना चाहता है, मानो उनके परिवार का इतिहास राम के विरुद्ध इस्तेमाल किया जा सके। अंगद यह विभाजन स्वीकार नहीं करते। वे राम-सेवा को अपना सचेत निर्णय बताते हैं और स्पष्ट करते हैं कि न लाभ का प्रलोभन, न पुरानी शिकायत दूतकार्य को विश्वासघात में बदलेगी।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'the-court-erupts-after-rama-is-insulted', 'en', 'Insults push the embassy beyond ordinary negotiation', 'When Ravana continues to insult Rama and orders Angada seized, anger overtakes the formal exchange. Angada strikes the ground with his arms, shaking the assembly and dislodging Ravana''s crowns; some are thrown back toward Rama''s camp. The spectacle makes the court''s instability visible before the decisive challenge begins.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'the-court-erupts-after-rama-is-insulted', 'hi', 'अपमान से दूतवार्ता सामान्य समझौते की सीमा पार करती है', 'रावण राम का अपमान जारी रखकर अंगद को पकड़ने का आदेश देता है तो औपचारिक वार्ता क्रोध में टूट जाती है। अंगद भुजाएँ धरती पर मारते हैं, सभा काँपती है और रावण के मुकुट गिर जाते हैं; कुछ मुकुट राम के शिविर की ओर फेंके जाते हैं। निर्णायक चुनौती से पहले ही यह दृश्य सभा की अस्थिरता सबके सामने ला देता है।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-plants-his-foot', 'en', 'Angada plants one foot and binds his claim to Rama''s strength', 'Angada plants his foot in the assembly and challenges Ravana''s warriors to move it. The wager is deliberately extreme because Angada''s confidence rests on Rama''s authority, not on a claim that Sita is his to give away. The scene presents the planted foot as a test of the court''s boasts and a final public warning.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'angada-plants-his-foot', 'hi', 'अंगद चरण रोपकर अपनी प्रतिज्ञा राम के बल से जोड़ते हैं', 'अंगद सभा में अपना चरण रोपकर रावण के योद्धाओं को उसे हटाने की चुनौती देते हैं। प्रतिज्ञा अत्यंत कठोर है, पर अंगद का विश्वास अपनी निजी शक्ति से अधिक राम के प्रताप पर टिका है; सीता पर उनका स्वामित्व नहीं बताया गया है। रोपा हुआ चरण सभा के दावों की परीक्षा और अंतिम सार्वजनिक चेतावनी बनता है।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'no-warrior-can-move-the-foot', 'en', 'Ravana''s strongest warriors fail before the whole court', 'Indrajit and many powerful warriors seize Angada''s foot and strain to move it, but it remains fixed. One after another they withdraw with lowered heads. The challenge converts verbal confidence into a visible result: Lanka''s champions cannot shift even the envoy whose master they have dismissed as powerless.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'no-warrior-can-move-the-foot', 'hi', 'रावण के बलवान योद्धा पूरी सभा के सामने असफल होते हैं', 'इंद्रजीत सहित अनेक बलवान योद्धा अंगद का चरण पकड़कर पूरी शक्ति लगाते हैं, पर वह तनिक नहीं हिलता। एक-एक करके सब सिर झुकाकर लौटते हैं। मौखिक घमंड अब सबके सामने परिणाम बन जाता है: जिन राम को वे निर्बल बताते रहे, उनके दूत का चरण भी लंका के वीर नहीं हटा पाते।'),
  ('ramayana-manas-angada-immovable-foot-v1', 'ravana-reaches-and-angada-withdraws', 'en', 'Angada redirects Ravana toward Rama and leaves the court', 'When Ravana himself rises to grasp the foot, Angada withdraws it and says that holding his foot cannot save the king; Ravana should instead hold Rama''s feet. Ravana returns to his throne humiliated but unchanged. Angada offers further counsel, then leaves after the final embassy has failed and war becomes unavoidable.'),
  ('ramayana-manas-angada-immovable-foot-v1', 'ravana-reaches-and-angada-withdraws', 'hi', 'अंगद रावण को राम के चरणों की ओर भेजकर सभा छोड़ते हैं', 'जब रावण स्वयं चरण पकड़ने उठता है, अंगद पैर हटा लेते हैं और कहते हैं कि दूत का चरण पकड़ने से रक्षा नहीं होगी; उसे राम के चरण पकड़ने चाहिए। रावण लज्जित होकर सिंहासन पर लौटता है, पर निर्णय नहीं बदलता। अंगद फिर नीति समझाकर निकल जाते हैं; अंतिम दूत-प्रयास विफल होता है और युद्ध टलने की संभावना समाप्त हो जाती है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'lakshmana-falls-and-time-runs-short', 'en', 'Lakshmana''s wound turns the battle into a race against dawn', 'Lakshmana is carried back unconscious after the enemy''s devastating strike. Rama grieves while Jambavan and the healer Sushena identify the life-restoring medicine needed before the night ends. Hanuman accepts the mission and leaves with Rama''s purpose fixed in his heart, because delay now threatens Lakshmana''s life.'),
  ('ramayana-manas-kalnemi-deception-v1', 'lakshmana-falls-and-time-runs-short', 'hi', 'लक्ष्मण का घाव युद्ध को प्रभात से पहले की दौड़ बना देता है', 'शत्रु के प्रचंड प्रहार के बाद लक्ष्मण अचेत अवस्था में शिविर लाए जाते हैं। राम शोक करते हैं, जबकि जाम्बवान और वैद्य सुषेण रात समाप्त होने से पहले आवश्यक जीवनदायिनी औषधि बताते हैं। हनुमान राम का उद्देश्य हृदय में रखकर निकलते हैं, क्योंकि अब हर विलंब लक्ष्मण के जीवन को संकट में डालता है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'ravana-orders-kalnemi-to-delay-hanuman', 'en', 'Ravana asks Kalnemi to stop the messenger he already fears', 'A spy tells Ravana that Hanuman has departed for the medicine. Ravana goes to Kalnemi and commands him to block the journey. Kalnemi knows that the being who burned Lanka cannot easily be stopped and urges Ravana to abandon hostility toward Rama, but Ravana answers the warning with coercion and threat.'),
  ('ramayana-manas-kalnemi-deception-v1', 'ravana-orders-kalnemi-to-delay-hanuman', 'hi', 'रावण कालनेमि को उसी दूत को रोकने भेजता है जिससे वह डरता है', 'एक गुप्तचर रावण को बताता है कि हनुमान औषधि लेने निकल चुके हैं। रावण कालनेमि के पास जाकर यात्रा रोकने का आदेश देता है। कालनेमि जानता है कि लंका जलाने वाले दूत को रोकना सरल नहीं और रावण को राम-विरोध छोड़ने की सलाह देता है, पर रावण चेतावनी का उत्तर दबाव और धमकी से देता है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'kalnemi-chooses-deception-under-threat', 'en', 'Kalnemi builds a false refuge on Hanuman''s path', 'Faced with death at Ravana''s hands or danger from Hanuman, Kalnemi goes ahead with the scheme. Through illusion he creates the appearance of a peaceful hermitage, water and a trustworthy ascetic. The trap is designed for urgency: a tired traveller racing to save someone may accept help without examining it closely.'),
  ('ramayana-manas-kalnemi-deception-v1', 'kalnemi-chooses-deception-under-threat', 'hi', 'कालनेमि हनुमान के मार्ग में झूठा आश्रम बनाता है', 'रावण के हाथों मृत्यु और हनुमान से टकराव के बीच कालनेमि छल की योजना स्वीकार करता है। माया से वह शांत आश्रम, जल और विश्वसनीय तपस्वी जैसा रूप बनाता है। जाल हनुमान की जल्दी को लक्ष्य करता है: किसी का जीवन बचाने दौड़ता थका यात्री बिना जाँच के सहायता स्वीकार कर सकता है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'the-false-sage-offers-water-and-initiation', 'en', 'The false sage tries to convert urgency into delay', 'Hanuman reaches the hermitage and asks for water. Kalnemi, disguised as a sage, speaks as though he can see the distant battle and offers instruction after Hanuman bathes in the lake. The performance mixes useful-sounding knowledge with unnecessary ritual so that each apparently harmless step consumes the time Lakshmana does not have.'),
  ('ramayana-manas-kalnemi-deception-v1', 'the-false-sage-offers-water-and-initiation', 'hi', 'झूठा साधु हनुमान की जल्दी को विलंब में बदलना चाहता है', 'हनुमान आश्रम पहुँचकर जल माँगते हैं। साधु बने कालनेमि दूर का युद्ध देखने का दावा करता है और सरोवर में स्नान के बाद मंत्र देने की बात कहता है। उसका अभिनय उपयोगी लगने वाली जानकारी को अनावश्यक प्रक्रिया से मिलाता है, ताकि हर निर्दोष दिखने वाला कदम वह समय खा जाए जो लक्ष्मण के पास नहीं है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'the-crocodile-becomes-an-apsara-and-warns-hanuman', 'en', 'An attack in the lake breaks the illusion', 'In the lake a crocodile attacks Hanuman, who kills it while defending himself. The creature is released into the form of an apsara freed from a curse. Before departing, she identifies the supposed sage as a demon and warns Hanuman that the hermitage is a trap, turning Kalnemi''s hidden plan into knowledge Hanuman can act upon.'),
  ('ramayana-manas-kalnemi-deception-v1', 'the-crocodile-becomes-an-apsara-and-warns-hanuman', 'hi', 'सरोवर का आक्रमण माया का पर्दा तोड़ देता है', 'सरोवर में एक मगर हनुमान पर आक्रमण करता है और वे आत्मरक्षा में उसे मार देते हैं। वह शाप से मुक्त अप्सरा के रूप में प्रकट होती है। जाने से पहले वह बताती है कि कथित साधु वास्तव में राक्षस है और पूरा आश्रम जाल है; अब कालनेमि की छिपी योजना ऐसी जानकारी बन जाती है जिस पर हनुमान तुरंत कार्रवाई कर सकते हैं।'),
  ('ramayana-manas-kalnemi-deception-v1', 'hanuman-demands-guru-fee-first', 'en', 'Hanuman reverses the deceiver''s performance', 'Hanuman returns without revealing the warning and asks the false teacher to accept his fee before giving the promised instruction. He then seizes and strikes Kalnemi. The demon''s assumed form collapses; at death he remembers Rama, and the obstacle created to waste the night is removed without diverting Hanuman into a prolonged contest.'),
  ('ramayana-manas-kalnemi-deception-v1', 'hanuman-demands-guru-fee-first', 'hi', 'हनुमान छल करने वाले का अभिनय उसी पर पलट देते हैं', 'हनुमान चेतावनी प्रकट किए बिना लौटते हैं और झूठे गुरु से कहते हैं कि मंत्र देने से पहले दक्षिणा ले लें। फिर वे कालनेमि को पकड़कर प्रहार करते हैं। राक्षस का बनाया रूप टूट जाता है; मरते समय वह राम का स्मरण करता है और रात नष्ट करने के लिए बनाया गया अवरोध लंबी लड़ाई बने बिना हट जाता है।'),
  ('ramayana-manas-kalnemi-deception-v1', 'hanuman-lifts-the-mountain-and-races-home', 'en', 'Unable to identify the herb, Hanuman carries the mountain', 'Hanuman reaches the mountain but cannot confidently distinguish the required plant among its many luminous herbs. Rather than gamble with Lakshmana''s life, he lifts the relevant mountain mass and turns back toward Lanka. The mission has survived Ravana''s deception, but its immense silhouette now creates a new misunderstanding over Ayodhya.'),
  ('ramayana-manas-kalnemi-deception-v1', 'hanuman-lifts-the-mountain-and-races-home', 'hi', 'औषधि न पहचान पाने पर हनुमान पर्वत ही उठा लेते हैं', 'हनुमान पर्वत तक पहुँचते हैं, पर अनेक चमकती औषधियों में आवश्यक वनस्पति को निश्चित रूप से नहीं पहचान पाते। लक्ष्मण के जीवन पर अनुमान लगाने के बजाय वे पर्वत का भाग ही उठा लेते हैं और लंका की ओर लौटते हैं। रावण का छल विफल हो चुका है, पर आकाश में विशाल आकृति अब अयोध्या के ऊपर नई गलतफहमी पैदा करती है।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-sees-a-figure-over-ayodhya', 'en', 'A mountain-shaped shadow crosses Bharata''s night watch', 'While living apart from royal comfort and waiting for Rama''s return, Bharata sees a vast figure carrying a mountain through the night above Ayodhya. He cannot recognize Hanuman at that distance and fears a hostile being is crossing the protected realm. The same urgency that drives Hanuman now forces Bharata to judge an unknown threat.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-sees-a-figure-over-ayodhya', 'hi', 'भरत की रात्रि-दृष्टि के ऊपर पर्वत जैसी छाया गुजरती है', 'राजसुख से दूर रहकर राम की वापसी की प्रतीक्षा करते भरत रात में अयोध्या के ऊपर पर्वत लिए विशाल आकृति देखते हैं। दूरी से वे हनुमान को नहीं पहचान पाते और मानते हैं कि कोई शत्रु राज्य के ऊपर से जा रहा है। जो आपात स्थिति हनुमान को दौड़ा रही है, वही भरत को अज्ञात खतरे पर तुरंत निर्णय लेने को बाध्य करती है।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharatas-blunt-arrow-brings-hanuman-down', 'en', 'Bharata uses a blunt arrow, and Hanuman falls calling Rama', 'Bharata chooses an arrow without a killing head and shoots the unknown traveller. The force brings Hanuman down while the mountain is kept from destroying the city. As he falls, Hanuman speaks Rama''s name. That single name immediately changes the situation from defence against an intruder to alarm that a servant of Rama has been harmed.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharatas-blunt-arrow-brings-hanuman-down', 'hi', 'भरत फलरहित बाण चलाते हैं और हनुमान राम कहते हुए गिरते हैं', 'भरत मारक फल के बिना बाण चुनकर अज्ञात यात्री पर चलाते हैं। प्रहार से हनुमान नीचे गिरते हैं, जबकि पर्वत नगर को नष्ट नहीं करता। गिरते समय हनुमान राम का नाम लेते हैं। वही एक नाम परिस्थिति बदल देता है: अब यह घुसपैठिए से रक्षा नहीं, राम के सेवक को चोट पहुँच जाने की चिंता है।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-tries-to-revive-the-stranger', 'en', 'Bharata embraces Hanuman and fears another separation from Rama', 'Bharata rushes to Hanuman, holds him to his chest and tries repeatedly to wake him. When Hanuman does not respond, Bharata grieves that the same fate which separated him from Rama may now have made him injure Rama''s devoted messenger. His reaction is responsibility and sorrow, not celebration of a successful shot.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-tries-to-revive-the-stranger', 'hi', 'भरत हनुमान को हृदय से लगाकर राम से एक और दूरी का भय महसूस करते हैं', 'भरत दौड़कर हनुमान को हृदय से लगाते हैं और बार-बार जगाने का प्रयास करते हैं। उत्तर न मिलने पर वे दुखी होते हैं कि जिस भाग्य ने उन्हें राम से दूर किया, कहीं उसी ने राम के समर्पित दूत को उनके हाथों चोट तो नहीं पहुँचा दी। उनकी प्रतिक्रिया सफल निशाने का गर्व नहीं, उत्तरदायित्व और शोक है।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharatas-devotion-calls-hanuman-back', 'en', 'Bharata stakes his sincerity on Hanuman''s recovery', 'Bharata invokes the truth of his love for Rama and asks that Hanuman recover if that devotion is sincere. Hanuman awakens and praises Rama, and Bharata''s grief turns into relief. Recognition is achieved not through a royal badge or military password but through their shared relationship to the absent Rama.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharatas-devotion-calls-hanuman-back', 'hi', 'भरत अपनी निष्कपट रामभक्ति पर हनुमान के उठने की प्रार्थना रखते हैं', 'भरत अपनी निष्कपट रामभक्ति की सत्यता स्मरण करके प्रार्थना करते हैं कि यदि उनका प्रेम सच्चा है तो हनुमान स्वस्थ होकर उठें। हनुमान जागकर राम का जयघोष करते हैं और भरत का शोक राहत में बदल जाता है। पहचान किसी राजचिह्न या सैन्य संकेत से नहीं, अनुपस्थित राम से दोनों के साझा संबंध से होती है।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-explains-lakshmanas-danger', 'en', 'Hanuman tells Bharata why every moment matters', 'Hanuman explains the war, Lakshmana''s unconscious condition, Sushena''s instruction and the difficulty of identifying the herb. The mountain is not a weapon aimed at Ayodhya but the safest way to carry the needed medicine back in time. Bharata now understands both his mistake and the life-or-death deadline still running.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-explains-lakshmanas-danger', 'hi', 'हनुमान भरत को बताते हैं कि हर क्षण क्यों महत्वपूर्ण है', 'हनुमान युद्ध, लक्ष्मण की अचेत अवस्था, सुषेण की औषधि और वनस्पति पहचानने की कठिनाई समझाते हैं। पर्वत अयोध्या पर चलाया गया हथियार नहीं, आवश्यक औषधि समय पर पहुँचाने का सबसे सुरक्षित उपाय है। भरत अब अपनी भूल और अभी भी चल रही जीवन-मरण की समय-सीमा दोनों समझते हैं।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-offers-his-arrow-as-transport', 'en', 'Bharata offers to carry Hanuman and the mountain on his arrow', 'To repair the delay, Bharata offers an extraordinary solution: Hanuman can mount the arrow with the mountain and be sent swiftly toward Rama. The offer shows both Bharata''s power and his desire to serve a crisis far beyond Ayodhya. He does not demand control of the mission after learning its purpose.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'bharata-offers-his-arrow-as-transport', 'hi', 'भरत हनुमान और पर्वत को अपने बाण पर भेजने का प्रस्ताव देते हैं', 'हुए विलंब की भरपाई के लिए भरत असाधारण उपाय देते हैं: हनुमान पर्वत सहित उनके बाण पर बैठें और वे उन्हें शीघ्र राम के पास पहुँचा दें। प्रस्ताव भरत की शक्ति के साथ दूर चल रहे संकट में सेवा की इच्छा दिखाता है। उद्देश्य जानने के बाद वे अभियान का नियंत्रण अपने हाथ में लेने की माँग नहीं करते।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-catches-and-releases-a-proud-thought', 'en', 'Hanuman briefly doubts the arrow, then recognizes Bharata''s strength', 'Hanuman momentarily wonders how one arrow could bear his weight and the mountain, then recognizes that this doubt underestimates Bharata''s strength and devotion. He honours Bharata but chooses to continue under his own power, carrying the renewed assurance of another person wholly committed to Rama''s welfare.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-catches-and-releases-a-proud-thought', 'hi', 'हनुमान क्षणभर बाण पर संदेह करके भरत का सामर्थ्य पहचानते हैं', 'हनुमान क्षणभर सोचते हैं कि एक बाण उनका और पर्वत का भार कैसे उठाएगा, फिर समझते हैं कि यह संदेह भरत के सामर्थ्य और भक्ति को कम आँकता है। वे भरत का सम्मान करते हैं, पर अपनी गति से आगे बढ़ते हैं और राम के हित में पूर्ण समर्पित एक और व्यक्ति का विश्वास साथ लेकर उड़ते हैं।'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-resumes-the-race-to-lanka', 'en', 'The mistaken encounter becomes help rather than lasting conflict', 'Hanuman bows, remembers Rama and launches again with the mountain. Bharata''s shot caused a dangerous interruption, but recognition, remorse and practical assistance prevent it from becoming a second conflict. The narrative returns to Rama waiting beside Lakshmana as Hanuman races to deliver the medicine before the remaining time expires.'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'hanuman-resumes-the-race-to-lanka', 'hi', 'गलत पहचान स्थायी संघर्ष के बजाय सहायता में बदल जाती है', 'हनुमान प्रणाम करके राम का स्मरण करते हैं और पर्वत सहित फिर उड़ते हैं। भरत के बाण ने खतरनाक रुकावट पैदा की थी, पर पहचान, पश्चात्ताप और व्यावहारिक सहायता उसे दूसरे संघर्ष में बदलने से रोकते हैं। कथा फिर लक्ष्मण के पास प्रतीक्षा करते राम की ओर लौटती है, जबकि हनुमान शेष समय समाप्त होने से पहले औषधि पहुँचाने दौड़ते हैं।')
) as source(moment_slug, beat_slug, language_code, title, narration)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-war-messengers-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
join public.narrative_beats beat on beat.moment_id=moment.id and beat.slug=source.beat_slug
on conflict (beat_id, language_code) do update set title=excluded.title, narration=excluded.narration, text_status=excluded.text_status,
  rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_moment_links (source_moment_id, target_moment_id, link_kind, label)
select source_moment.id, target_moment.id, source.link_kind, 'source-ordered expected-story traversal'
from (values
  ('ramayana-manas-angada-immovable-foot-v1', 'ramayana-manas-kalnemi-deception-v1', 'precedes'),
  ('ramayana-manas-kalnemi-deception-v1', 'ramayana-manas-angada-immovable-foot-v1', 'follows'),
  ('ramayana-manas-kalnemi-deception-v1', 'ramayana-manas-bharata-shoots-hanuman-v1', 'precedes'),
  ('ramayana-manas-bharata-shoots-hanuman-v1', 'ramayana-manas-kalnemi-deception-v1', 'follows')
) as source(source_slug, target_slug, link_kind)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-war-messengers-v1'
join public.narrative_moments source_moment on source_moment.series_id=series.id and source_moment.slug=source.source_slug
join public.narrative_moments target_moment on target_moment.series_id=series.id and target_moment.slug=source.target_slug
on conflict (source_moment_id, target_moment_id, link_kind) do update set label=excluded.label;

insert into public.narrative_evidence (moment_id, passage_id, evidence_role, note)
select moment.id, passage.id, 'source_span', 'Pinned Ramcharitmanas page within the exact story scan range'
from public.narrative_series series
join public.narrative_moments moment on moment.series_id=series.id
join public.passages passage on passage.locator->>'scan_sha256'=moment.source_range->>'scanSha256'
  and (passage.locator->>'scan_page')::integer between (moment.source_range->'scanPagesInclusive'->>0)::integer
  and (moment.source_range->'scanPagesInclusive'->>1)::integer
where series.slug='ramcharitmanas-expected-stories-war-messengers-v1'
on conflict (moment_id, beat_id, passage_id, evidence_role) do update set note=excluded.note;

do $devam$
declare story_count integer; beat_count integer; bilingual_story_text_count integer; bilingual_beat_text_count integer;
begin
  select count(*) into story_count from public.narrative_moments moment join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramcharitmanas-expected-stories-war-messengers-v1' and moment.source_range->>'snapshotContract'='DEVAM_RAMAYANA_EXPECTED_STORIES_WAR_MESSENGERS_DB_V1';
  select count(*) into beat_count from public.narrative_beats beat join public.narrative_moments moment on moment.id=beat.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramcharitmanas-expected-stories-war-messengers-v1';
  select count(*) into bilingual_story_text_count from public.narrative_moment_texts text join public.narrative_moments moment on moment.id=text.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramcharitmanas-expected-stories-war-messengers-v1';
  select count(*) into bilingual_beat_text_count from public.narrative_beat_texts text join public.narrative_beats beat on beat.id=text.beat_id
  join public.narrative_moments moment on moment.id=beat.moment_id join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramcharitmanas-expected-stories-war-messengers-v1';
  if story_count <> 3 then raise exception 'Expected 3 Ramcharitmanas expected stories, got %', story_count; end if;
  if beat_count <> 25 then raise exception 'Expected 25 Ramcharitmanas expected-story beats, got %', beat_count; end if;
  if bilingual_story_text_count <> 6 then raise exception 'Expected 6 bilingual story texts, got %', bilingual_story_text_count; end if;
  if bilingual_beat_text_count <> 50 then raise exception 'Expected 50 bilingual beat texts, got %', bilingual_beat_text_count; end if;
end
$devam$;

commit;
